import { describe, expect, it } from 'vitest'
import { PeopleMatcher, Pseudonymizer, placeholderCounts } from '../src/recipe/index.ts'

// The leaks seen on the pilot (STOP S4), rebuilt with invented people, companies and meetings:
// a transcript with first names and pet names, a Teams and a Webex invitation, a signature with a
// disclaimer, a subject with a tag. Nothing here is real data; the ids are generated by hand.

const hex = (n: number, seed: number) => {
  let out = ''
  let x = seed
  for (let i = 0; i < n; i += 1) {
    x = (x * 1103515245 + 12345) % 2147483648
    out += (x % 16).toString(16)
  }
  return out
}
const guid = (seed: number) =>
  [hex(8, seed), hex(4, seed + 1), hex(4, seed + 2), hex(4, seed + 3), hex(12, seed + 4)].join('-')

describe('first names, surnames and pet names alone', () => {
  const people = [
    { displayName: 'Andrea Fumagalli', email: 'a.fumagalli@lumenaria.it' },
    { displayName: 'Claudio Bertolazzi', trust: 'seen' as const },
    { displayName: 'Giuseppe Moranduzzo', trust: 'untrusted' as const },
  ]

  it('a first name alone of a known person is hidden in a transcript', () => {
    const p = new Pseudonymizer(people)
    const text = [
      'Trascrizione della riunione',
      '[00:00:05] Andrea Fumagalli: Buongiorno a tutti, Giuseppe ci sei?',
      '[00:00:09] Giuseppe Moranduzzo: Sì, eccomi. Fumagalli mi senti?',
      '[00:00:12] Claudio Bertolazzi: giuseppe, prima la demo.',
    ].join('\n')
    const out = p.pseudonymize(text)
    for (const word of ['Andrea', 'Fumagalli', 'Giuseppe', 'giuseppe', 'Claudio', 'Moranduzzo']) {
      expect(out).not.toContain(word)
    }
    expect(out).toContain('Buongiorno a tutti')
    expect(p.restore(out)).toBe(text)
  })

  it('a common diminutive of a known first name is hidden', () => {
    const p = new Pseudonymizer(people)
    const text = 'Andre, Clau e Peppe confermano; Beppe manda il verbale, Andy lo rilegge.'
    const out = p.pseudonymize(text)
    for (const word of ['Andre', 'Clau', 'Peppe', 'Beppe', 'Andy']) expect(out).not.toContain(word)
    expect(out).toContain('confermano')
    expect(p.restore(out)).toBe(text)
  })

  it('a first name shared by two people becomes an ambiguous placeholder', () => {
    const p = new Pseudonymizer([
      { displayName: 'Andrea Fumagalli' },
      { displayName: 'Andrea Lisciandro', trust: 'seen' },
      // The same person listed twice (a member and a source) is one person, never ambiguous.
      { displayName: 'Fumagalli, Andrea', trust: 'untrusted' },
    ])
    const out = p.pseudonymize('Andrea conferma, Fumagalli no, Lisciandro forse.')
    expect(out).toMatch(/^\[PERSONA_AMBIGUA_1\] conferma, \[PERSONA_1\] no, \[PERSONA_2\] forse\.$/)
    // The full name is still the person's own.
    expect(p.pseudonymize('Andrea Lisciandro')).toBe('[PERSONA_2A]')
    expect(p.restore(out)).toBe('Andrea conferma, Fumagalli no, Lisciandro forse.')
  })

  it('a common word that is also a first name stays when it is not a name', () => {
    const p = new Pseudonymizer([
      { displayName: 'Rosa Quintavalle' },
      { displayName: 'Will Harrowgate', trust: 'untrusted' },
      { displayName: 'Bianca Zoppolato', trust: 'seen' },
    ])
    expect(p.pseudonymize('la rosa dei venti e la maglia bianca')).toBe(
      'la rosa dei venti e la maglia bianca',
    )
    expect(p.pseudonymize('Rosa dei venti: il colore scelto.')).toBe(
      'Rosa dei venti: il colore scelto.',
    )
    expect(p.pseudonymize('We will ship. Will it work?')).toBe('We will ship. Will it work?')
    // As a name: with a capital inside a sentence, after a greeting, as a vocative.
    expect(p.pseudonymize('Ne parla Rosa domani')).not.toContain('Rosa')
    expect(p.pseudonymize('ciao rosa, a dopo')).not.toContain('rosa')
    expect(p.pseudonymize('Grazie Will')).not.toContain('Will')
    expect(p.pseudonymize('Bianca, mi senti?')).not.toContain('Bianca')
  })

  it('never hides a frequent word for a short form of a first name', () => {
    const p = new Pseudonymizer([
      { displayName: 'Graziella Tomasoni' },
      { displayName: 'Luigi Brembati' },
      { displayName: 'Orazio Pellicari', trust: 'seen' },
      { displayName: 'Salvatore Ruggerini' },
      { displayName: 'Ivan Castelvetri' },
      { displayName: 'Gennaro Vitiello' },
      { displayName: 'Ottavio Lancellotti' },
      { displayName: 'Monica Ferrabosco' },
      { displayName: 'Federico Albanesi' },
      { displayName: 'Claudio Rinaldoni' },
      { displayName: 'Marco Pizzighetti' },
    ])
    const text =
      'Grazie mille. Lui dice che Ora è pronto il SAL, IVA esclusa, Sal e Fed lo sanno. ' +
      'Gen 2026, Ott 2026, Mon Nov 9, Mar 3. Cla.'
    expect(p.pseudonymize(text)).toBe(text)
  })

  it('a short form shared by two people is ambiguous', () => {
    const p = new Pseudonymizer([
      { displayName: 'Daniele Ombrosi' },
      { displayName: 'Daniela Carpegna' },
    ])
    expect(p.pseudonymize('Ne parla Dani domani')).toBe('Ne parla [PERSONA_AMBIGUA_1] domani')
  })

  it('finds the short forms of a first name written after the surname', () => {
    const p = new Pseudonymizer([{ displayName: 'Brembati Giuseppe', trust: 'seen' }])
    expect(p.pseudonymize('Ne parla Peppe')).toBe('Ne parla [PERSONA_1]')
  })

  it('hides a name written without its accents, in any case, and restores it exactly', () => {
    const p = new Pseudonymizer([
      { displayName: 'Nicolò Galli' },
      { displayName: 'Maria-Grazia Fois' },
    ])
    const text = 'Ciao Nicolo, NICOLO ha detto, Nicolò conferma, Mariagrazia anche.'
    const out = p.pseudonymize(text)
    for (const word of ['Nicolo', 'NICOLO', 'Nicolò', 'Mariagrazia'])
      expect(out).not.toContain(word)
    expect(p.restore(out)).toBe(text)
  })

  it('never takes a lower-case word of the text for a pet name', () => {
    const p = new Pseudonymizer([{ displayName: 'Francesco Pellizzari' }])
    expect(p.pseudonymize('il franco svizzero e fra le altre cose')).toBe(
      'il franco svizzero e fra le altre cose',
    )
    expect(p.pseudonymize('Fra le altre cose lo dice Checco.')).toBe(
      'Fra le altre cose lo dice [PERSONA_1].',
    )
  })
})

describe('names with decorations', () => {
  it("a person's name with a team suffix or a tag stays hidden", () => {
    for (const [displayName, trust] of [
      ['Mario Rossi - Team Delivery', 'seen'],
      ['Mario Rossi (Ufficio Acquisti)', 'seen'],
      ['Mario Rossi | Acme Support', 'untrusted'],
      ['Mario Rossi (Admin)', undefined],
      ['[EXT] Mario Rossi', 'untrusted'],
      ['Rossi Mario <m.rossi@acme.example>', 'untrusted'],
      ['Mario Rossi2', 'untrusted'],
    ] as const) {
      const p = new Pseudonymizer([{ displayName, ...(trust ? { trust } : {}) }])
      const out = p.pseudonymize('Mario Rossi conferma; Rossi lo dice al team e al supporto.')
      expect(out, displayName).not.toMatch(/Mario|Rossi/)
      // The decoration is never registered as the person.
      expect(out, displayName).toContain('al team e al supporto')
    }
  })

  it("a person's name inside a role decoration stays hidden", () => {
    const text =
      'Mario Rossi ha scritto. Rossi conferma, Anna Verdi e Verdi anche; il Helpdesk risponde.'
    for (const displayName of [
      'Helpdesk - Mario Rossi',
      'Servizio Clienti - Mario Rossi',
      'Project Manager - Mario Rossi',
      'Support (Mario Rossi)',
      'IT Support (Mario Rossi)',
      '[Mario Rossi]',
      'Team Lead | Anna Verdi',
    ]) {
      for (const trust of [undefined, 'seen', 'untrusted'] as const) {
        const p = new Pseudonymizer([{ displayName, ...(trust ? { trust } : {}) }])
        const out = p.pseudonymize(text)
        const person = displayName.includes('Verdi') ? /Anna|Verdi/ : /Mario|Rossi/
        expect(out, `${displayName} ${trust ?? 'member'}`).not.toMatch(person)
        // The role is never hidden as the person.
        expect(out, `${displayName} ${trust ?? 'member'}`).toContain('il Helpdesk risponde')
        expect(p.restore(out)).toBe(text)
      }
    }
  })

  it('a name in brackets with joined words is a person for every source', () => {
    for (const [displayName, text, hidden] of [
      ['[Mario.Rossi]', 'Ne parla Mario Rossi, poi Rossi.', /Mario|Rossi/],
      ['[mario_rossi]', 'Ne parla Mario Rossi, poi Rossi.', /Mario|Rossi/],
      ['[Rossi-Bianchi]', 'Ne parla Rossi-Bianchi, poi Bianchi.', /Rossi|Bianchi/],
    ] as const) {
      for (const trust of ['seen', 'untrusted'] as const) {
        const p = new Pseudonymizer([{ displayName, trust }])
        expect(p.pseudonymize(text), `${displayName} ${trust}`).not.toMatch(hidden)
      }
    }
    // One word in brackets written in capitals is the tag of a subject, never a person.
    const tag = new Pseudonymizer([{ displayName: '[PORTALEQUARZO]', trust: 'seen' }])
    expect(tag.pseudonymize('[PORTALEQUARZO] avanzamento')).toBe('[PORTALEQUARZO] avanzamento')
  })

  it('a user name alone in brackets, all in small letters, is a person, not a tag', () => {
    const seen = new Pseudonymizer([{ displayName: '[mrossi]', trust: 'seen' }])
    expect(seen.pseudonymize('[mrossi] avanzamento; ne parla mrossi.')).not.toContain('mrossi')
    // A common word alone in small letters stays a label.
    const label = new Pseudonymizer([{ displayName: '[avanzamento]', trust: 'seen' }])
    expect(label.pseudonymize('[avanzamento] della settimana')).toBe(
      '[avanzamento] della settimana',
    )
  })

  it('a user name in brackets is a member when a member has it, and an outsider like any other', () => {
    const text = '[mrossi] avanzamento; ne parla mrossi.'
    const member = new Pseudonymizer([{ displayName: '[mrossi]' }])
    expect(member.pseudonymize(text)).not.toContain('mrossi')
    // An outsider's name of one word is never hidden alone (the general rule of outsiders): in
    // brackets or not, the same.
    const bracketed = new Pseudonymizer([{ displayName: '[mrossi]', trust: 'untrusted' }])
    const plain = new Pseudonymizer([{ displayName: 'mrossi', trust: 'untrusted' }])
    expect(bracketed.pseudonymize(text)).toBe(plain.pseudonymize(text))
  })

  it('a surname that is a role word stays hidden with a capital for a seen person too', () => {
    for (const trust of ['seen', 'untrusted'] as const) {
      const p = new Pseudonymizer([
        { displayName: 'Mario Product', trust },
        { displayName: 'Anna Lead', trust },
      ])
      const out = p.pseudonymize('Product conferma, Lead ok; il product owner e il lead time.')
      expect(out, trust).not.toMatch(/Product|Lead/)
      expect(out, trust).toContain('il product owner e il lead time')
    }
  })

  it('keeps the names that were already hidden with words of the text in them', () => {
    const p = new Pseudonymizer([
      { displayName: 'Luca Porta' },
      { displayName: 'Marco Ferro', trust: 'seen' },
      { displayName: 'Anna Martello', trust: 'seen' },
      { displayName: '[EXT] Team Rossi', trust: 'seen' },
      { displayName: 'Bianchi (Admin) Support', trust: 'seen' },
    ])
    const out = p.pseudonymize('Luca Porta, Marco Ferro, Anna Martello, Rossi e Bianchi scrivono.')
    for (const word of [
      'Luca',
      'Porta',
      'Marco',
      'Ferro',
      'Anna',
      'Martello',
      'Rossi',
      'Bianchi',
    ]) {
      expect(out, word).not.toContain(word)
    }
    expect(out).toContain('scrivono')
  })

  it('keeps hiding names a group word would have dropped', () => {
    const p = new Pseudonymizer([
      { displayName: 'LUCA', trust: 'seen' },
      { displayName: 'Maria Teresa de la Cruz Fernández López', trust: 'seen' },
      { displayName: 'Mario Info' },
      { displayName: 'Giulia Staff' },
      { displayName: 'Luca Bot' },
      { displayName: 'Anna Area' },
    ])
    const out = p.pseudonymize(
      'LUCA, Fernández López, Info, Staff, Bot e Area ne parlano: Mario Info e Anna Area.',
    )
    for (const word of ['LUCA', 'Fernández', 'López', 'Info', 'Staff', 'Bot', 'Mario', 'Anna']) {
      expect(out, word).not.toContain(word)
    }
  })

  it('registers only the address of a name that is certainly not a person', () => {
    const p = new Pseudonymizer([
      { displayName: 'Team Delivery', email: 'quarzolina.delivery@acme.example', trust: 'seen' },
      { displayName: '[PORTALEQUARZO]', trust: 'untrusted' },
    ])
    expect(p.pseudonymize('il team delivery del portalequarzo')).toBe(
      'il team delivery del portalequarzo',
    )
    expect(p.pseudonymize('scrivi a quarzolina')).toBe('scrivi a [PERSONA_1]')
  })
})

describe('meetings and identifiers', () => {
  const tenant = guid(11)
  const oid = guid(29)
  const teamsJoin =
    `https://teams.microsoft.com/l/meetup-join/19%3ameeting_${hex(40, 3)}%40thread.v2/0` +
    `?context=%7b%22Tid%22%3a%22${tenant}%22%2c%22Oid%22%3a%22${oid}%22%7d`
  const teamsMeet = `https://teams.microsoft.com/meet/${hex(14, 5).replace(/[a-f]/g, '7')}?p=${hex(16, 9)}`
  const dialin = `https://dialin.teams.microsoft.com/${guid(41)}?id=${hex(9, 13).replace(/[a-f]/g, '3')}`
  const webex = `https://lumenaria.webex.com/msteams?confid=${hex(9, 17).replace(/[a-f]/g, '1')}&tenantkey=lumenaria&domain=webex.com`
  const invite = [
    'Riunione di Microsoft Teams',
    'Partecipa dal computer, dall’app mobile o dal dispositivo della stanza',
    `Fai clic qui per partecipare alla riunione <${teamsJoin}>`,
    `Partecipa: ${teamsMeet}`,
    'ID riunione: 312 845 990 117',
    'Passcode: Xk7pQ2',
    'Chiama (solo audio)',
    `+39 02 4000 1234,,889123456# Italy, Milan`,
    'ID conferenza telefonica: 889 123 456#',
    `Trova un numero locale <${dialin}>`,
    'Partecipa da un dispositivo per videoconferenze',
    'ID video: 118 222 333 4',
    `Partecipa con Webex: ${webex}`,
    'PIN 552190#',
  ].join('\n')

  it('a meeting join link is hidden whole', () => {
    const p = new Pseudonymizer([])
    const out = p.pseudonymize(invite)
    for (const link of [teamsJoin, teamsMeet, dialin, webex]) expect(out).not.toContain(link)
    for (const piece of ['meetup-join', 'context=', 'Tid', 'confid', 'tenantkey', '?p=']) {
      expect(out).not.toContain(piece)
    }
    expect(out).toContain('Fai clic qui per partecipare alla riunione <[LINK_RIUNIONE_1]>')
    expect(placeholderCounts(out).LINK_RIUNIONE).toBe(4)
    expect(p.restore(out)).toBe(invite)
  })

  it('a meeting passcode is hidden', () => {
    const p = new Pseudonymizer([])
    const out = p.pseudonymize(invite)
    for (const value of ['312 845 990 117', 'Xk7pQ2', '889 123 456#', '118 222 333 4', '552190#']) {
      expect(out).not.toContain(value)
    }
    // The label stays: the model still knows what the line was.
    expect(out).toContain('Passcode: [CODICE_RIUNIONE_')
    expect(out).toContain('ID riunione: [CODICE_RIUNIONE_')
    expect(out).toContain('PIN [CODICE_RIUNIONE_')
    for (const line of [
      'Meeting password: 5pXm7Q',
      'Password: Xy12Ab',
      'Chiave del tenant: acmeTenant',
      "Codice d'accesso: aB3dE5",
      'Codice d’accesso: aB3dE6',
      'Codice d accesso: aB3dE7',
      'Codice di accesso: aB3dE8',
      'Codice conferenza: 445566',
      'PIN code: 7788',
      'Codice PIN: 7789',
      'ID partecipante: 9911#',
      'Codice daccesso: aB3dE9',
      'Host key: 123456',
      'Chiave host: 654321',
      'Pwd: Zq8Tq2',
    ]) {
      const hidden = p.pseudonymize(line)
      expect(hidden, line).toMatch(/: \[CODICE_RIUNIONE_\d+\]$/)
      expect(p.restore(hidden)).toBe(line)
    }
    // Words after a label without a colon stay words.
    expect(p.pseudonymize('il PIN della carta va cambiato')).toBe('il PIN della carta va cambiato')
    expect(p.restore(out)).toBe(invite)
  })

  it('a guid is hidden whole and never read as a phone number', () => {
    const p = new Pseudonymizer([])
    const plain = `tenant ${tenant} oggetto ${oid} e token ${hex(24, 77)}A9b`
    const out = p.pseudonymize(plain)
    expect(out).not.toContain('TELEFONO')
    expect(out).toMatch(/^tenant \[ID_1\] oggetto \[ID_2\] e token \[ID_3\]$/)
    // A GUID glued to the encoding of a quote is still one token, never half a phone number.
    const encoded = p.pseudonymize(`%22${guid(91)}%22`)
    expect(encoded).not.toContain('TELEFONO')
    expect(encoded.replace(/\[[A-Z_]+\d+[A-Z]*\]/g, '')).toBe('%%22')
    expect(p.restore(out)).toBe(plain)
  })

  it('never puts a credential back in clear in a model answer, and restores the rest', () => {
    const p = new Pseudonymizer([{ displayName: 'Andrea Fumagalli' }])
    const sent = p.pseudonymize(`Andrea Fumagalli: Passcode: Xk7pQ2 ${teamsMeet}`)
    const answer = sent.replace('Andrea Fumagalli', 'x')
    const back = p.restore(answer, { credentials: 'withheld' })
    expect(back).toContain('Andrea Fumagalli')
    expect(back).toMatch(/\[CODICE_RIUNIONE_1\] \[LINK_RIUNIONE_1\]$/)
    expect(p.restore(answer)).toBe(`Andrea Fumagalli: Passcode: Xk7pQ2 ${teamsMeet}`)
  })

  it('hides tokens of known services whole, never half a phone number', () => {
    const p = new Pseudonymizer([])
    // Built at run time: no secret-shaped literal in the repository.
    const tail = 'Qz7'.repeat(8)
    for (const prefix of ['ghp_', 'github_pat_', 'npm_', 'sk-', 'sk-proj-', 'glpat-', 'xoxb-']) {
      const token = `${prefix}${tail}12345678`
      const out = p.pseudonymize(`token ${token} fine`)
      expect(out, prefix).toMatch(/^token \[ID_\d+\] fine$/)
    }
  })

  it('hides a bearer token and a JWT whole, all three parts', () => {
    const p = new Pseudonymizer([])
    // Built at run time: no secret-shaped literal in the repository.
    const part = (seed: string) => `${seed}Qz7xW2`.repeat(3)
    const jwt = ['eyJ', part('a'), '.', part('b'), '.', part('c')].join('')
    const bearer = ['Ab9', '12345678', 'Zx.'.repeat(4), '9876'].join('')
    const text = `Authorization: Bearer ${bearer}\ntoken ${jwt} fine`
    const out = p.pseudonymize(text)
    expect(out).toBe('Authorization: Bearer [ID_1]\ntoken [ID_2] fine')
    expect(out).not.toContain('TELEFONO')
    expect(p.restore(out, { credentials: 'withheld' })).toContain('Bearer [ID_1]')
    expect(p.restore(out)).toBe(text)
  })

  it('keeps an identifier on a line of a tenant or a key hidden in a model answer', () => {
    const p = new Pseudonymizer([])
    const sent = p.pseudonymize(`Tenant id: ${tenant}\nElemento ${oid}`)
    expect(sent).toBe('Tenant id: [ID_1]\nElemento [ID_2]')
    expect(p.restore(sent, { credentials: 'withheld' })).toBe(`Tenant id: [ID_1]\nElemento ${oid}`)
    expect(p.restore(sent)).toBe(`Tenant id: ${tenant}\nElemento ${oid}`)
  })

  it('keeps words with dashes, names glued to numbers and plain numbers as they were read', () => {
    const p = new Pseudonymizer([])
    expect(p.pseudonymize('test end-to-end-integration-2026 ok')).toBe(
      'test end-to-end-integration-2026 ok',
    )
    expect(p.pseudonymize('report_2026_11_09_finale')).toBe('report_2026_11_09_finale')
  })
})

describe('organizations', () => {
  it('an organization from an email domain is hidden', () => {
    const p = new Pseudonymizer([
      { displayName: 'Lumenaria', kind: 'organization' },
      { displayName: 'Ferrovanti Impianti S.p.A.', kind: 'organization' },
    ])
    const text =
      "Lumenaria conferma; lo dice anche LUMENARIA e l'offerta di Lumenaria's partner. " +
      'Vedi lumenaria-impianti.it e www.lumenaria.com. Ferrovanti Impianti firma.'
    const out = p.pseudonymize(text)
    expect(out.toLowerCase()).not.toContain('lumenaria')
    expect(out).not.toContain('Ferrovanti')
    expect(out).toMatch(/^\[ORG_1\] conferma; lo dice anche \[ORG_1A\]/)
    expect(p.restore(out)).toBe(text)
  })

  it('hides a company written with its legal form in a signature or a disclaimer', () => {
    const p = new Pseudonymizer([{ displayName: 'Andrea Fumagalli' }])
    const text = [
      'Cordiali saluti',
      'Andrea Fumagalli',
      'Quarzolina Servizi S.r.l. - Via Inventata 1',
      'Questo messaggio è destinato a Brivadoro Holding SpA e a Tessilverde Ltd.',
    ].join('\n')
    const out = p.pseudonymize(text)
    for (const word of ['Quarzolina', 'Brivadoro', 'Tessilverde', 'Fumagalli']) {
      expect(out).not.toContain(word)
    }
    expect(out).toContain('Cordiali saluti')
    expect(placeholderCounts(out).ORG).toBe(3)
    expect(p.restore(out)).toBe(text)
  })

  it('hides legal forms written in lower case, never a wellness centre', () => {
    const p = new Pseudonymizer([])
    expect(p.pseudonymize('fornisce Fabrikam srl e anche Quarzolina spa.')).toBe(
      'fornisce [ORG_1] e anche [ORG_2].',
    )
    expect(p.pseudonymize('Ci vediamo al Centro Spa e poi al Hotel spa.')).toBe(
      'Ci vediamo al Centro Spa e poi al Hotel spa.',
    )
    expect(p.pseudonymize('soggiorno a Villa Spa Resort')).toBe('soggiorno a Villa Spa Resort')
    expect(p.pseudonymize('fornisce Tessiluna snc e Ferrovanti sas.')).toBe(
      'fornisce [ORG_3] e [ORG_4].',
    )
  })

  it('never hides one word of an organization alone', () => {
    const p = new Pseudonymizer([
      { displayName: 'Servizi Generali Torvaldo', kind: 'organization' },
    ])
    expect(p.pseudonymize('i servizi generali del cliente')).toBe('i servizi generali del cliente')
    expect(p.pseudonymize('Servizi Generali Torvaldo')).toBe('[ORG_1]')
  })
})

describe('tags and placeholders', () => {
  it('a tag in brackets in a mail subject is not taken for a person', () => {
    const p = new Pseudonymizer([{ displayName: 'Andrea Fumagalli' }])
    const text = 'Oggetto: [PORTALEQUARZO] Avanzamento settimanale - Andrea'
    const out = p.pseudonymize(text)
    expect(out).toBe('Oggetto: [PORTALEQUARZO] Avanzamento settimanale - [PERSONA_1]')
  })

  it('counts each kind of placeholder once per token', () => {
    const counts = placeholderCounts('[PERSONA_1] [PERSONA_1] [PERSONA_1A] [ORG_2] [ID_1] testo')
    // One person written two ways ([PERSONA_1], [PERSONA_1A]) is one person.
    expect(counts).toMatchObject({ PERSONA: 1, ORG: 1, ID: 1, EMAIL: 0, LINK_RIUNIONE: 0 })
  })

  it('escapes text shaped like the new placeholders so restore stays exact', () => {
    const p = new Pseudonymizer([])
    const text = 'già [ORG_1] e [LINK_RIUNIONE_2] e [PERSONA_AMBIGUA_1]'
    expect(p.restore(p.pseudonymize(text))).toBe(text)
    expect(p.pseudonymize(text)).not.toContain('[ORG_1]')
  })

  it('hides organizations and ambiguous names without numbers in the index-free mode', () => {
    const matcher = new PeopleMatcher([
      { displayName: 'Andrea Fumagalli' },
      { displayName: 'Andrea Lisciandro' },
      { displayName: 'Lumenaria', kind: 'organization' },
    ])
    const p = new Pseudonymizer(matcher, { placeholders: 'index-free' })
    expect(p.pseudonymize('Andrea di Lumenaria, Passcode: Xk7pQ2')).toBe(
      '[PERSONA] di [ORG], Passcode: [CODICE_RIUNIONE]',
    )
  })
})
